#[effects(alloc)]
fn render(d: &Diag, sm: &source::SourceMap) -> String {
    let a: source::Pos = sm.line_col(d.span.file, d.span.lo);
    let b: source::Pos = sm.line_col(d.span.file, d.span.hi);
    let mut s: String = String::from("{\"code\":");
    std::json::push_string(&mut s, d.code.as_str());
    s.push_str(",\"sev\":\"");
    push_severity(&mut s, d.code.as_str());
    s.push_str("\",\"message\":");
    std::json::push_string(&mut s, d.message.as_str());
    s.push_str(",\"file\":");
    sm.push_name(&mut s, d.span.file);
    s.push_str(",\"line\":");
    std::num::push_u64(&mut s, a.line as u64);
    s.push_str(",\"col\":");
    std::num::push_u64(&mut s, a.col as u64);
    s.push_str(",\"end_line\":");
    std::num::push_u64(&mut s, b.line as u64);
    s.push_str(",\"end_col\":");
    std::num::push_u64(&mut s, b.col as u64);
    match &d.obligation {
        None => {},
        Some(o) => { s.push_str(",\"obligation\":"); std::json::push_string(&mut s, o.as_str()); },
    }
    match &d.bounded {
        None => {},
        Some(k) => { s.push_str(",\"bounded\":{\"b\":"); std::num::push_i64(&mut s, k.b); s.push_str(",\"l\":"); std::num::push_u64(&mut s, k.l as u64); s.push_str("}"); },
    }
    match &d.fix {
        None => {},
        Some(f) => { s.push_str(",\"fix\":{\"message\":"); std::json::push_string(&mut s, f.message.as_str()); match &f.replacement { None => {}, Some(r) => { s.push_str(",\"replacement\":"); std::json::push_string(&mut s, r.as_str()); }, } s.push_str("}"); },
    }
    s.push_str("}");
    s
}

